/*111*/ "\u0623\u0648\u0644\u0627\u064b\u060c \u0633\u062c\u0651\u0644 ",
/*112*/ " \u0625\u0644\u0649 \u062d\u0633\u0627\u0628\u0643 \u0641\u064a ACS.",
/*113*/ ": \u0623\u0643\u0645\u0644 \u0627\u0644\u062a\u0633\u062c\u064a\u0644 \u0628\u0647\u0630\u0627 \u0627\u0644\u062f\u0648\u0631\u061b \u0648\u0645\u0646 \u0627\u0644\u0648\u0627\u062c\u0628 \u0625\u062f\u062e\u0627\u0644 \u062a\u0627\u0631\u064a\u062e \u0627\u0644\u0645\u064a\u0644\u0627\u062f (DOB) \u0627\u0644\u0635\u062d\u064a\u062d.",
/*114*/ ": \u0627\u0641\u062a\u062d\u0647.",
