/*139*/ "LinkedIn Premium Career \u00b7 \u0623\u0633\u0648\u0627\u0642 \u0639\u062f\u0629",
/*140*/ "\u0627\u0634\u062a\u0631\u0627\u0643 \u0627\u0644\u0645\u0633\u0627\u0631 \u0627\u0644\u0645\u0647\u0646\u064a \u064a\u0634\u0645\u0644 \u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 LinkedIn Learning \u0648\u063a\u064a\u0631\u0647 \u0645\u0646 \u0627\u0644\u062e\u062f\u0645\u0627\u062a.",
/*141*/ "\u0645\u0644\u0627\u062d\u0638\u0629:",
/*142*/ " \u0647\u0630\u0647 \u0645\u062c\u0631\u062f \u0623\u0645\u062b\u0644\u0629 \u0639\u0644\u0649 \u0646\u0645\u0648\u0630\u062c \u0627\u0644\u0639\u0636\u0648\u064a\u0629/\u0627\u0644\u0628\u0637\u0627\u0642\u0629. \u0644\u0627 \u0639\u0644\u0627\u0642\u0629 \u0644\u0640 ACS \u0628\u0647\u0627 \u0648\u0644\u0627 \u062a\u0642\u0627\u0631\u0646 \u062e\u062f\u0645\u0627\u062a \u0645\u0643\u0627\u0641\u0626\u0629\u061b \u0645\u0632\u0627\u064a\u0627 ACS Golden Pass \u0647\u064a \u0645\u0627 \u062a\u0643\u062a\u0628\u0647 \u0635\u0641\u062d\u0627\u062a ACS \u0635\u0631\u0627\u062d\u0629.",
