/*157*/ "\u0627\u0644\u062f\u0641\u0639",
/*158*/ "\u0639\u0644\u0649 \u0635\u0641\u062d\u0629 Razorpay \u0627\u0644\u0622\u0645\u0646\u0629. ACS \u0644\u0627 \u062a\u0631\u0649 \u0631\u0642\u0645 \u0628\u0637\u0627\u0642\u062a\u0643 \u0623\u0628\u062f\u0627\u064b.",
/*159*/ "\u0625\u064a\u0635\u0627\u0644 \u0627\u0644\u062f\u0641\u0639 (\u0631\u0642\u0645 \u0627\u0644\u0637\u0644\u0628 \u0648\u0627\u0644\u062d\u0627\u0644\u0629)",
/*160*/ "\u0645\u0644\u062e\u0635 \u062a\u0642\u0631\u064a\u0631 \u20b9125 (\u0627\u0644\u0627\u0633\u0645\u060c \u0627\u0633\u0645 \u0627\u0644\u0627\u062e\u062a\u0628\u0627\u0631\u060c \u0645\u0644\u062e\u0635 \u0627\u0644\u062f\u0631\u062c\u0627\u062a\u060c \u0627\u0644\u0631\u0642\u0645)",
/*161*/ "\u0639\u0644\u0649 \u062e\u0627\u062f\u0645 ACS. \u0648\u0639\u0644\u064a\u0647 \u064a\u0639\u062a\u0645\u062f \u062a\u062d\u0642\u0642 QR.",
/*162*/ "\u0645\u0627\u0630\u0627 \u064a\u0638\u0647\u0631 \u062a\u062d\u0642\u0642 QR\u061f",
/*163*/ "\u0631\u0642\u0645 \u0627\u0644\u062a\u0642\u0631\u064a\u0631 \u0648\u062d\u0627\u0644\u0629 \u0635\u062d\u062a\u0647 \u0641\u0642\u0637.",
/*164*/ "\u0627\u0644\u0645\u0639\u0627\u064a\u0646\u0629 \u0644\u0627 \u062a\u062d\u062a\u0627\u062c \u062d\u0633\u0627\u0628\u0627\u064b. \u0641\u064a \u0627\u0644\u0645\u0639\u0627\u064a\u0646\u0629\u060c \u0644\u0627 \u062a\u064f\u0631\u0633\u0644 \u0625\u062c\u0627\u0628\u0627\u062a\u0643 \u0648\u0644\u0627 \u0627\u0633\u0645\u0643 \u0648\u0644\u0627 \u0628\u064a\u0627\u0646\u0627\u062a \u062d\u0633\u0627\u0628\u0643 \u0625\u0644\u0649 \u062e\u0627\u062f\u0645 ACS. \u0632\u064a\u0627\u0631\u0629 \u0627\u0644\u0635\u0641\u062d\u0629 \u062a\u0646\u062a\u062c \u0633\u062c\u0644\u0627\u062a \u0648\u064a\u0628 \u0639\u0627\u062f\u064a\u0629\u060c \u0643\u0645\u0627 \u0641\u064a \u0643\u0644 \u0627\u0644\u0645\u0648\u0627\u0642\u0639.",
/*165*/ "\ud83d\udce2 \u062a\u0646\u0628\u064a\u0647 \u0644\u0645\u0646 \u0647\u0645 \u062f\u0648\u0646 18: \u0647\u0630\u0647 \u0623\u062f\u0627\u0629 \u0644\u0627\u0633\u062a\u0643\u0634\u0627\u0641 \u0627\u0644\u0645\u0647\u0646\u060c \u0644\u0627 \u0642\u0631\u0627\u0631 \u0645\u0647\u0646\u064a. \u0627\u0646\u0638\u0631 \u0627\u0644\u0646\u062a\u064a\u062c\u0629 \u0645\u0639 \u0648\u0627\u0644\u062f\u064a\u0643 \u0623\u0648 \u0648\u0644\u064a \u0623\u0645\u0631\u0643 \u0623\u0648 \u0645\u0639\u0644\u0645\u0643. \u0627\u0644\u062f\u0641\u0639 \u064a\u062a\u0637\u0644\u0628 \u0645\u0648\u0627\u0641\u0642\u0629 \u0648\u0644\u064a \u0627\u0644\u0623\u0645\u0631. \u0645\u0646 10 \u0625\u0644\u0649 13 \u0633\u0646\u0629\u060c \u0627\u0639\u062a\u0628\u0631\u0647 \u062a\u0645\u0631\u064a\u0646 \u0627\u0633\u062a\u0643\u0634\u0627\u0641\u060c \u0644\u0627 \u062a\u0642\u064a\u064a\u0645\u0627\u064b \u0631\u0633\u0645\u064a\u0627\u064b.",
/*166*/ "\ud83d\udcdc \u0645\u0627\u0630\u0627 \u0641\u064a \u062a\u0642\u0631\u064a\u0631 \u20b9125\u061f \u0634\u0627\u0647\u062f \u0627\u0644\u0646\u0645\u0648\u0630\u062c",
