/*230*/ "\ud83e\udded \u0627\u062e\u062a\u0628\u0627\u0631 \u0627\u0644\u0645\u064a\u0648\u0644 \u0627\u0644\u0645\u0647\u0646\u064a\u0629 \u0645\u0646 ACS (Career Interest Test): \u0635\u0646\u0639 \u0641\u064a \u0627\u0644\u0647\u0646\u062f\u060c \u0648\u0627\u0644\u0645\u0639\u0627\u064a\u0646\u0629 \u0628\u0627\u0644\u0625\u0646\u062c\u0644\u064a\u0632\u064a\u0629 \u0648\u0627\u0644\u0647\u0646\u062f\u064a\u0629. \u0645\u0639\u0627\u064a\u0646\u0629 24 \u0633\u0624\u0627\u0644\u0627\u064b: \u20b90. \u0627\u0644\u0627\u062e\u062a\u0628\u0627\u0631 \u0627\u0644\u0643\u0627\u0645\u0644 \u0645\u0646 120 \u0633\u0624\u0627\u0644\u0627\u064b: \u20b9100 \u0644\u0643\u0644 \u0645\u062d\u0627\u0648\u0644\u0629\u061b \u0648\u0631\u0624\u064a\u0629 \u0627\u0644\u0646\u062a\u064a\u062c\u0629 \u0628\u0644\u0627 \u0631\u0633\u0648\u0645 \u0625\u0636\u0627\u0641\u064a\u0629. \u0645\u0639 Golden Pass \u0633\u0627\u0631\u064a\u0629\u060c \u0627\u0644\u0627\u062e\u062a\u0628\u0627\u0631 \u0627\u0644\u0643\u0627\u0645\u0644 \u0628\u0644\u0627 \u062d\u062f\u0648\u062f. \u062a\u0642\u0631\u064a\u0631 \u0642\u0627\u0628\u0644 \u0644\u0644\u0637\u0628\u0627\u0639\u0629: \u20b9125\u060c \u0627\u0634\u062a\u0631\u0647 \u0641\u0642\u0637 \u0625\u0646 \u0623\u0631\u062f\u062a\u0647.",
/*231*/ "\ud83d\ude80 \u0627\u0641\u062a\u062d \u0635\u0641\u062d\u0629 \u0627\u0644\u0627\u062e\u062a\u0628\u0627\u0631 \u2190",
/*232*/ "\u2696\ufe0f \u0647\u0646\u0627\u0643 \u0648\u0647\u0646\u0627: \u0627\u0646\u0638\u0631 \u0627\u0644\u0641\u0631\u0642",
